/**
 * The types `save/export-info/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    ExportInfoSaveExtract
 * depends    —
 * used by    src/save/export-info/index, src/save/export-info/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */

/** What an official export says about itself, and whether this SDK has been checked against it. */
export interface ExportInfoSaveExtract {
  /** Format version of the External Tools export. 1 for every export so far. */
  exportVersion: number | null
  /** When the game wrote the export, ISO. */
  exportedAt: string | null
  /** The game's build number (1286 is v29.2.0, 1294 is v29.2.1, 1296 is v29.2.2, 1301 is v29.2.3). */
  versionNumber: number | null
  /** The game's save-data version. Renames such as the `_v2` shard keys come with a bump. */
  dataVersion: number | null
  /** True when the export is no newer than the newest one this SDK was checked against. */
  checked: boolean
  /** Top-level fields the SDK's field catalog does not name: new, or renamed. */
  unknownKeys: string[]
  warnings: string[]
}
